def compute(vars):
    old = vars["v1"]
    new = vars["v2"]

    if old == 0:
        return None

    decrease_ratio = (old - new) / old
    value = decrease_ratio * 100

    return {
        "value": value,
        "trace": {
            "old_average_borrowings": old,
            "new_average_borrowings": new,
            "decrease_ratio": decrease_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
